SELECT foundation_test.expect_error($q$UPDATE public.projects SET ownership='client',client_organization_id='31000000-0000-4000-8000-000000000003',internal_initiative_id=NULL WHERE id='50000000-0000-4000-8000-000000000001'$q$,'23503','project client cannot cross organization');
SELECT foundation_test.expect_error($q$UPDATE public.projects SET client_organization_id='31000000-0000-4000-8000-000000000001' WHERE id='50000000-0000-4000-8000-000000000001'$q$,'23514','internal project cannot acquire a client');
SELECT foundation_test.expect_error($q$UPDATE public.projects SET engagement_id='34000000-0000-4000-8000-000000000001' WHERE id='50000000-0000-4000-8000-000000000001'$q$,'23514','internal project cannot require a commercial agreement');
SELECT foundation_test.expect_error($q$UPDATE public.projects SET internal_initiative_id='33000000-0000-4000-8000-000000000001' WHERE id='50000000-0000-4000-8000-000000000002'$q$,'23514','client project cannot attach an internal initiative');
SELECT foundation_test.expect_error($q$UPDATE public.projects SET client_organization_id=NULL,engagement_id=NULL WHERE id='50000000-0000-4000-8000-000000000002'$q$,'23514','client project requires its business');
SELECT foundation_test.expect_error($q$UPDATE public.projects SET client_organization_id='31000000-0000-4000-8000-000000000002' WHERE id='50000000-0000-4000-8000-000000000002'$q$,'23503','commercial agreement must belong to the selected client');
SELECT foundation_test.expect_error($q$UPDATE public.projects SET work_context_id='40000000-0000-4000-8000-000000000005' WHERE id='50000000-0000-4000-8000-000000000001'$q$,'23503','project cannot use an operational context');
SELECT foundation_test.expect_error($q$UPDATE public.work_contexts SET kind='operational' WHERE id='40000000-0000-4000-8000-000000000001'$q$,'23514','context kind is immutable');
SELECT foundation_test.expect_error($q$UPDATE public.work_contexts SET organization_id='20000000-0000-4000-8000-000000000002' WHERE id='40000000-0000-4000-8000-000000000001'$q$,'23514','context tenant is immutable');
SELECT foundation_test.expect_error($q$INSERT INTO public.work_contexts(id,organization_id,kind,created_by) VALUES('a4000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','project','10000000-0000-4000-8000-000000000001'); SET CONSTRAINTS ALL IMMEDIATE$q$,'23514','context requires business parent before commit');

SELECT foundation_test.expect_error($q$UPDATE public.tasks SET column_id='61000000-0000-4000-8000-000000000002',board_id='60000000-0000-4000-8000-000000000002',category='review' WHERE id='70000000-0000-4000-8000-000000000001'$q$,'23503','task cannot use a board from another context');
SELECT foundation_test.expect_error($q$UPDATE public.tasks SET category='done' WHERE id='70000000-0000-4000-8000-000000000001'$q$,'23503','task category must match authoritative home column');
SELECT foundation_test.expect_error($q$UPDATE public.tasks SET board_id=NULL,column_id=NULL WHERE id='70000000-0000-4000-8000-000000000001'$q$,'23514','project task needs one home workflow');
SELECT foundation_test.expect_error($q$UPDATE public.tasks SET column_id=NULL WHERE id='70000000-0000-4000-8000-000000000001'$q$,'23514','board and column must both exist');
SELECT foundation_test.expect_error($q$DELETE FROM public.board_columns WHERE id='61000000-0000-4000-8000-000000000001'$q$,'23001','populated column deletion cannot cascade into task loss');
SELECT foundation_test.expect_error($q$DELETE FROM public.boards WHERE id='60000000-0000-4000-8000-000000000001'$q$,'23001','populated board deletion cannot cascade into task loss');
SELECT foundation_test.assert((SELECT count(*) FROM public.tasks WHERE id='70000000-0000-4000-8000-000000000001')=1,'blocked configuration deletion preserves task identity');
SELECT foundation_test.assert((SELECT board_id IS NULL AND column_id IS NULL FROM public.tasks WHERE id='70000000-0000-4000-8000-000000000005'),'operational task can be unboarded without a fake project');
SELECT foundation_test.expect_error($q$INSERT INTO public.task_assignees(organization_id,work_context_id,task_id,user_id) VALUES('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000004')$q$,'23503','assignment task/context IDs must match');
SELECT foundation_test.expect_error($q$INSERT INTO public.task_assignees(organization_id,work_context_id,task_id,user_id) VALUES('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000007')$q$,'23514','client cannot be an internal task assignee');
SELECT foundation_test.expect_error($q$INSERT INTO public.work_context_memberships(organization_id,work_context_id,user_id,role) VALUES('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000009','manager')$q$,'23514','inactive member cannot receive production membership');
SELECT foundation_test.expect_error($q$INSERT INTO public.client_access_grants(organization_id,client_organization_id,contact_id,project_id,scope,granted_by) VALUES('20000000-0000-4000-8000-000000000001','31000000-0000-4000-8000-000000000002','32000000-0000-4000-8000-000000000003','50000000-0000-4000-8000-000000000002','project_publications','10000000-0000-4000-8000-000000000001')$q$,'23503','client publication grant cannot target a different client project');
SELECT foundation_test.expect_error($q$INSERT INTO public.client_contacts(organization_id,client_organization_id,name,email) VALUES('20000000-0000-4000-8000-000000000002','31000000-0000-4000-8000-000000000001','Mismatched contact','invalid-scope@example.invalid')$q$,'23503','contact cannot cross studio/client scope');

